mapper.delete:
delete
from setmeal_dish
where setmeal_id in #{setmealId}

mapper.select:
select s.* ,c.name categoryName from setmeal s left join category c
on s.category_id = c.id

    and s.name like concat('%',#{name},'%')

    and category_id =#{categoryId}

     and s.status =#{status}


order by s.create_time desc
